"""Registered semantic capabilities for the remote Worker ingress.

The public semantic boundary never accepts raw Worker actions/checks at the
top-level HTTP schema. Each capability expands an objective into one
deterministic Worker v2 request under fail-closed validation.
"""
from __future__ import annotations

from dataclasses import dataclass
from pathlib import Path
import re
from typing import Any, Callable, Mapping

from tools.mirror_sync.readonly_audit_profiles import (
    is_allowed_readonly_audit_profile,
)
from tools.mirror_sync.universal_job_bridge import (
    MAX_ACTIONS,
    MAX_TEXT_BYTES,
    READ_ONLY_CHECKS,
    safe_repo_path,
    validate_check,
)


REPO_ROOT = Path(__file__).resolve().parents[3]
_SHA256_RE = re.compile(r"^[0-9a-f]{64}$")
_GIT_SHA_RE = re.compile(r"^[0-9a-f]{40}$")
_DOMAIN_TOKEN_RE = re.compile(r"^[A-Za-z0-9][A-Za-z0-9._-]{0,119}$")

_STRUCTURED_V2_MODES = (
    "READ_ONLY",
    "READ_ONLY_SQL",
    "MUTATION",
    "FRONTEND_BUILD_CERTIFICATION",
)

_STRUCTURED_V2_ALLOWED_CONSTRAINTS = frozenset(
    {
        "actions",
        "checks",
        "base_sha",
        "audit_profile",
        "paths",
        "search_terms",
        "include_patterns",
        "exclude_patterns",
        "max_results",
        "directory",
        "required_deliverables",
        "deliverable_specs",
        "acceptance_criteria",
        "expected_native_decision",
        "priority_class",
        "conflict_domains",
        "resource_claims",
    }
)

_FORBIDDEN_NESTED_KEYS = frozenset(
    {
        "command",
        "commands",
        "shell",
        "script",
        "script_body",
        "raw_sql",
        "sql",
        "requester",
        "production_allowed",
        "target_repo",
        "target_branch",
        "schema",
        "human_summary_language",
        "password",
        "passwd",
        "secret",
        "secrets",
        "token",
        "credential",
        "credentials",
        "api_key",
        "apikey",
    }
)

_V1_LEGACY_ACTION_KEYS = frozenset({"old", "new", "expected_count"})
_MUTATION_ALLOWED_CHECKS = frozenset(
    {
        "git_diff_check",
        "py_compile",
        "pytest",
        "frontend_build",
        "repository_contract_audit",
    }
)
_READ_ONLY_SEMANTIC_CHECKS = frozenset(READ_ONLY_CHECKS - {"sql_readonly_audit"})
_FRONTEND_BUILD_ALLOWED_CHECKS = frozenset(
    {
        "frontend_build",
        "git_diff_check",
        "repository_contract_audit",
    }
)


class SemanticCapabilityError(ValueError):
    pass


@dataclass(frozen=True)
class SemanticCapability:
    code: str
    modes: tuple[str, ...]
    builder: Callable[[Mapping[str, Any]], dict[str, Any]]


_CAPABILITIES: dict[str, SemanticCapability] = {}


def register_capability(capability: SemanticCapability) -> None:
    code = str(capability.code or "").strip().upper()
    if not code:
        raise SemanticCapabilityError("SEMANTIC_CAPABILITY_CODE_REQUIRED")
    if code in _CAPABILITIES:
        raise SemanticCapabilityError("SEMANTIC_CAPABILITY_DUPLICATE")
    if not capability.modes:
        raise SemanticCapabilityError("SEMANTIC_CAPABILITY_MODE_REQUIRED")
    _CAPABILITIES[code] = capability


def registered_capabilities() -> tuple[str, ...]:
    return tuple(sorted(_CAPABILITIES))


def resolve_capability(code: str) -> SemanticCapability:
    value = str(code or "").strip().upper()
    capability = _CAPABILITIES.get(value)
    if capability is None:
        raise SemanticCapabilityError("SEMANTIC_CAPABILITY_UNKNOWN")
    return capability


def _assert_no_forbidden_nested_keys(value: Any) -> None:
    if isinstance(value, Mapping):
        for raw_key, nested in value.items():
            normalized = str(raw_key).strip().lower()
            if normalized in _FORBIDDEN_NESTED_KEYS:
                raise SemanticCapabilityError(
                    f"SEMANTIC_FORBIDDEN_KEY:{normalized}"
                )
            _assert_no_forbidden_nested_keys(nested)
    elif isinstance(value, (list, tuple)):
        for item in value:
            _assert_no_forbidden_nested_keys(item)


def _validate_v2_action(action: Any, index: int) -> dict[str, Any]:
    if not isinstance(action, Mapping):
        raise SemanticCapabilityError(f"SEMANTIC_ACTION_{index}_NOT_OBJECT")

    item = dict(action)
    if any(key in item for key in _V1_LEGACY_ACTION_KEYS):
        raise SemanticCapabilityError("SEMANTIC_ACTION_V2_REQUIRED")

    kind = str(item.get("type") or "").strip()
    path = item.get("path")
    if not safe_repo_path(path):
        raise SemanticCapabilityError(f"SEMANTIC_ACTION_{index}_INVALID_PATH")
    clean_path = str(path)

    if (
        kind == "write_file"
        and Path(clean_path).parts[:2] == ("backend", "core")
        and not (REPO_ROOT / clean_path).exists()
    ):
        raise SemanticCapabilityError("SEMANTIC_CORE_GROWTH_FORBIDDEN")

    if kind in {"replace_text", "insert_before", "insert_after", "append_once"}:
        source_sha = item.get("source_sha256")
        if not isinstance(source_sha, str) or not _SHA256_RE.fullmatch(source_sha):
            raise SemanticCapabilityError(
                "SEMANTIC_ACTION_SOURCE_SHA256_INVALID"
            )

        replacement = item.get("replacement")
        if not isinstance(replacement, str):
            raise SemanticCapabilityError(
                "SEMANTIC_ACTION_REPLACEMENT_REQUIRED"
            )
        if len(replacement.encode("utf-8")) > MAX_TEXT_BYTES:
            raise SemanticCapabilityError("SEMANTIC_ACTION_CONTENT_TOO_LARGE")

        expected_occurrences = item.get("expected_occurrences", 1)
        if (
            not isinstance(expected_occurrences, int)
            or isinstance(expected_occurrences, bool)
            or expected_occurrences < 1
            or expected_occurrences > 1000
        ):
            raise SemanticCapabilityError(
                "SEMANTIC_ACTION_EXPECTED_OCCURRENCES_INVALID"
            )

        if kind == "replace_text":
            allowed_keys = {
                "type",
                "path",
                "source_sha256",
                "old_text",
                "replacement",
                "expected_occurrences",
            }
            if set(item) - allowed_keys:
                raise SemanticCapabilityError("SEMANTIC_ACTION_KEYS_INVALID")
            old_text = item.get("old_text")
            if not isinstance(old_text, str) or not old_text:
                raise SemanticCapabilityError(
                    "SEMANTIC_ACTION_OLD_TEXT_REQUIRED"
                )
            return {
                "type": "replace_text",
                "path": clean_path,
                "source_sha256": source_sha,
                "old_text": old_text,
                "replacement": replacement,
                "expected_occurrences": expected_occurrences,
            }

        if kind in {"insert_before", "insert_after"}:
            allowed_keys = {
                "type",
                "path",
                "source_sha256",
                "anchor",
                "replacement",
                "expected_occurrences",
            }
            if set(item) - allowed_keys:
                raise SemanticCapabilityError("SEMANTIC_ACTION_KEYS_INVALID")
            anchor = item.get("anchor")
            if not isinstance(anchor, str) or not anchor:
                raise SemanticCapabilityError(
                    "SEMANTIC_ACTION_ANCHOR_REQUIRED"
                )
            return {
                "type": kind,
                "path": clean_path,
                "source_sha256": source_sha,
                "anchor": anchor,
                "replacement": replacement,
                "expected_occurrences": expected_occurrences,
            }

        allowed_keys = {
            "type",
            "path",
            "source_sha256",
            "replacement",
            "expected_occurrences",
        }
        if set(item) - allowed_keys:
            raise SemanticCapabilityError("SEMANTIC_ACTION_KEYS_INVALID")
        return {
            "type": "append_once",
            "path": clean_path,
            "source_sha256": source_sha,
            "replacement": replacement,
            "expected_occurrences": expected_occurrences,
        }

    if kind == "write_file":
        allowed_keys = {"type", "path", "content", "expected_sha256"}
        if set(item) - allowed_keys:
            raise SemanticCapabilityError("SEMANTIC_ACTION_KEYS_INVALID")
        content = item.get("content")
        if not isinstance(content, str):
            raise SemanticCapabilityError("SEMANTIC_ACTION_CONTENT_REQUIRED")
        if len(content.encode("utf-8")) > MAX_TEXT_BYTES:
            raise SemanticCapabilityError("SEMANTIC_ACTION_CONTENT_TOO_LARGE")
        normalized: dict[str, Any] = {
            "type": "write_file",
            "path": clean_path,
            "content": content,
        }
        if item.get("expected_sha256") is not None:
            expected_sha = item.get("expected_sha256")
            if not isinstance(expected_sha, str) or not _SHA256_RE.fullmatch(
                expected_sha
            ):
                raise SemanticCapabilityError(
                    "SEMANTIC_ACTION_EXPECTED_SHA256_INVALID"
                )
            normalized["expected_sha256"] = expected_sha
        return normalized

    if kind == "delete_file":
        allowed_keys = {"type", "path", "expected_sha256"}
        if set(item) - allowed_keys:
            raise SemanticCapabilityError("SEMANTIC_ACTION_KEYS_INVALID")
        expected_sha = item.get("expected_sha256")
        if not isinstance(expected_sha, str) or not _SHA256_RE.fullmatch(
            expected_sha
        ):
            raise SemanticCapabilityError(
                "SEMANTIC_ACTION_EXPECTED_SHA256_INVALID"
            )
        return {
            "type": "delete_file",
            "path": clean_path,
            "expected_sha256": expected_sha,
        }

    raise SemanticCapabilityError("SEMANTIC_ACTION_TYPE_FORBIDDEN")


def _validate_checks_list(
    raw_checks: Any,
    *,
    allowed_types: frozenset[str],
) -> list[dict[str, Any]]:
    if not isinstance(raw_checks, list) or not raw_checks:
        raise SemanticCapabilityError("SEMANTIC_CHECKS_INVALID")

    normalized: list[dict[str, Any]] = []
    for index, raw_check in enumerate(raw_checks, 1):
        if not isinstance(raw_check, Mapping):
            raise SemanticCapabilityError(f"SEMANTIC_CHECK_{index}_NOT_OBJECT")
        check = dict(raw_check)
        kind = str(check.get("type") or "").strip()
        if kind not in allowed_types:
            raise SemanticCapabilityError(
                f"SEMANTIC_CHECK_TYPE_FORBIDDEN:{kind or 'EMPTY'}"
            )
        errors = validate_check(check, index)
        if errors:
            raise SemanticCapabilityError(
                "SEMANTIC_CHECK_INVALID:" + ",".join(errors)
            )
        normalized.append(check)
    return normalized


def _validate_domain_tokens(value: Any, error_code: str) -> list[str]:
    if not isinstance(value, list) or not value or len(value) > 16:
        raise SemanticCapabilityError(error_code)
    tokens: list[str] = []
    for item in value:
        token = str(item or "").strip().upper()
        if not token or not _DOMAIN_TOKEN_RE.fullmatch(token):
            raise SemanticCapabilityError(error_code)
        if token not in tokens:
            tokens.append(token)
    return tokens


def _read_only_canary_builder(request: Mapping[str, Any]) -> dict[str, Any]:
    constraints = request.get("constraints")
    constraints = dict(constraints) if isinstance(constraints, Mapping) else {}
    if constraints:
        unknown = sorted(constraints)
        raise SemanticCapabilityError(
            "SEMANTIC_CONSTRAINTS_UNSUPPORTED:" + ",".join(unknown)
        )

    bounded_context = str(request.get("bounded_context") or "").strip().upper()
    return {
        "actions": [],
        "checks": [{"type": "git_diff_check"}],
        "scheduling": {
            "project_id": "EDARSAHUB",
            "bounded_context": bounded_context,
            "priority_class": "NORMAL",
            "fairness_weight": 1,
            "max_parallelism": 1,
            "resource_claims": [],
            "conflict_domains": [bounded_context],
        },
    }


def _structured_v2_objective_builder(
    request: Mapping[str, Any],
) -> dict[str, Any]:
    raw_constraints = request.get("constraints")
    if raw_constraints is None:
        constraints: dict[str, Any] = {}
    elif not isinstance(raw_constraints, Mapping):
        raise SemanticCapabilityError("SEMANTIC_CONSTRAINTS_INVALID")
    else:
        constraints = dict(raw_constraints)

    unknown = sorted(
        str(key)
        for key in (set(constraints) - _STRUCTURED_V2_ALLOWED_CONSTRAINTS)
    )
    if unknown:
        raise SemanticCapabilityError(
            "SEMANTIC_CONSTRAINTS_UNSUPPORTED:" + ",".join(unknown)
        )

    _assert_no_forbidden_nested_keys(constraints)

    bounded_context = (
        str(request.get("bounded_context") or "").strip().upper() or "EDARSAHUB"
    )
    mode = str(request.get("mode") or "").strip().upper()
    capability_code = str(request.get("capability") or "").strip().upper()

    base_sha = constraints.get("base_sha")
    if base_sha is not None:
        if not isinstance(base_sha, str) or not _GIT_SHA_RE.fullmatch(base_sha):
            raise SemanticCapabilityError("SEMANTIC_BASE_SHA_INVALID")

    actions: list[dict[str, Any]] = []
    checks: list[dict[str, Any]] = []
    audit_profile: str | None = None

    if mode == "MUTATION":
        for disallowed in (
            "audit_profile",
            "paths",
            "search_terms",
            "include_patterns",
            "exclude_patterns",
            "max_results",
            "directory",
        ):
            if disallowed in constraints:
                raise SemanticCapabilityError(
                    f"SEMANTIC_CONSTRAINTS_MODE_MISMATCH:{disallowed}"
                )

        raw_actions = constraints.get("actions")
        if not isinstance(raw_actions, list) or not raw_actions:
            raise SemanticCapabilityError("SEMANTIC_ACTIONS_REQUIRED")
        if len(raw_actions) > MAX_ACTIONS:
            raise SemanticCapabilityError("SEMANTIC_TOO_MANY_ACTIONS")
        actions = [
            _validate_v2_action(item, idx)
            for idx, item in enumerate(raw_actions, 1)
        ]

        raw_checks = constraints.get("checks")
        if raw_checks is None:
            checks = [{"type": "git_diff_check"}]
        else:
            checks = _validate_checks_list(
                raw_checks,
                allowed_types=_MUTATION_ALLOWED_CHECKS,
            )

    elif mode == "READ_ONLY":
        if constraints.get("actions") not in (None, []):
            raise SemanticCapabilityError(
                "SEMANTIC_READ_ONLY_ACTIONS_FORBIDDEN"
            )
        for disallowed in ("audit_profile", "directory"):
            if disallowed in constraints:
                raise SemanticCapabilityError(
                    f"SEMANTIC_CONSTRAINTS_MODE_MISMATCH:{disallowed}"
                )

        raw_checks = constraints.get("checks")
        has_shorthand = any(
            key in constraints
            for key in (
                "paths",
                "search_terms",
                "include_patterns",
                "exclude_patterns",
                "max_results",
            )
        )
        if raw_checks is not None and has_shorthand:
            raise SemanticCapabilityError(
                "SEMANTIC_DUPLICATE_AUDIT_SCOPE_CONSTRAINTS"
            )

        if raw_checks is not None:
            checks = _validate_checks_list(
                raw_checks,
                allowed_types=_READ_ONLY_SEMANTIC_CHECKS,
            )
        elif has_shorthand:
            audit_request: dict[str, Any] = {
                "paths": constraints.get("paths"),
                "search_terms": constraints.get("search_terms"),
            }
            for optional_field in (
                "include_patterns",
                "exclude_patterns",
                "max_results",
            ):
                if optional_field in constraints:
                    audit_request[optional_field] = constraints[optional_field]
            audit_check = {
                "type": "repository_contract_audit",
                "request": audit_request,
            }
            errors = validate_check(audit_check, 1)
            if errors:
                raise SemanticCapabilityError(
                    "SEMANTIC_CHECK_INVALID:" + ",".join(errors)
                )
            checks = [audit_check, {"type": "git_diff_check"}]
        elif capability_code in {
            "REPOSITORY_CONTRACT_AUDIT",
            "REPOSITORY_ARCHITECTURE_AUDIT",
        }:
            raise SemanticCapabilityError(
                "SEMANTIC_REPOSITORY_AUDIT_SCOPE_REQUIRED"
            )
        else:
            checks = [{"type": "git_diff_check"}]

    elif mode == "READ_ONLY_SQL":
        if constraints.get("actions") not in (None, []):
            raise SemanticCapabilityError(
                "SEMANTIC_READ_ONLY_SQL_ACTIONS_FORBIDDEN"
            )
        if constraints.get("checks") not in (None, []):
            raise SemanticCapabilityError(
                "SEMANTIC_READ_ONLY_SQL_INLINE_CHECKS_FORBIDDEN"
            )
        for disallowed in (
            "paths",
            "search_terms",
            "include_patterns",
            "exclude_patterns",
            "max_results",
            "directory",
        ):
            if disallowed in constraints:
                raise SemanticCapabilityError(
                    f"SEMANTIC_CONSTRAINTS_MODE_MISMATCH:{disallowed}"
                )

        profile = str(constraints.get("audit_profile") or "").strip()
        if not profile or not is_allowed_readonly_audit_profile(profile):
            raise SemanticCapabilityError("SEMANTIC_AUDIT_PROFILE_INVALID")
        audit_profile = profile
        checks = []

    elif mode == "FRONTEND_BUILD_CERTIFICATION":
        if constraints.get("actions") not in (None, []):
            raise SemanticCapabilityError(
                "SEMANTIC_FRONTEND_BUILD_ACTIONS_FORBIDDEN"
            )
        for disallowed in (
            "audit_profile",
            "paths",
            "search_terms",
            "include_patterns",
            "exclude_patterns",
            "max_results",
        ):
            if disallowed in constraints:
                raise SemanticCapabilityError(
                    f"SEMANTIC_CONSTRAINTS_MODE_MISMATCH:{disallowed}"
                )

        directory = str(constraints.get("directory") or "frontend").strip()
        if not safe_repo_path(directory):
            raise SemanticCapabilityError(
                "SEMANTIC_FRONTEND_DIRECTORY_INVALID"
            )

        raw_checks = constraints.get("checks")
        if raw_checks is None:
            checks = [
                {"type": "frontend_build", "directory": directory},
                {"type": "git_diff_check"},
            ]
        else:
            checks = _validate_checks_list(
                raw_checks,
                allowed_types=_FRONTEND_BUILD_ALLOWED_CHECKS,
            )
            if not any(c.get("type") == "frontend_build" for c in checks):
                raise SemanticCapabilityError(
                    "SEMANTIC_FRONTEND_BUILD_CHECK_REQUIRED"
                )
    else:
        raise SemanticCapabilityError("SEMANTIC_CAPABILITY_MODE_MISMATCH")

    priority_class = (
        str(constraints.get("priority_class") or "NORMAL").strip().upper()
    )
    if priority_class not in {"LOW", "NORMAL", "HIGH"}:
        raise SemanticCapabilityError("SEMANTIC_PRIORITY_CLASS_INVALID")

    if "conflict_domains" in constraints:
        conflict_domains = _validate_domain_tokens(
            constraints["conflict_domains"],
            "SEMANTIC_CONFLICT_DOMAINS_INVALID",
        )
    else:
        conflict_domains = [bounded_context]

    if mode == "MUTATION" and "GLOBAL_GIT_WRITER" not in conflict_domains:
        conflict_domains = ["GLOBAL_GIT_WRITER", *conflict_domains]

    if "resource_claims" in constraints:
        resource_claims = (
            []
            if constraints["resource_claims"] == []
            else _validate_domain_tokens(
                constraints["resource_claims"],
                "SEMANTIC_RESOURCE_CLAIMS_INVALID",
            )
        )
    else:
        resource_claims = []

    expansion: dict[str, Any] = {
        "actions": actions,
        "checks": checks,
        "scheduling": {
            "project_id": "EDARSAHUB",
            "bounded_context": bounded_context,
            "priority_class": priority_class,
            "fairness_weight": 1,
            "max_parallelism": 1,
            "resource_claims": resource_claims,
            "conflict_domains": conflict_domains,
        },
    }
    if base_sha is not None:
        expansion["base_sha"] = base_sha
    if audit_profile is not None:
        expansion["audit_profile"] = audit_profile

    for optional_key in (
        "required_deliverables",
        "deliverable_specs",
        "acceptance_criteria",
        "expected_native_decision",
    ):
        if optional_key in constraints and constraints[optional_key] is not None:
            expansion[optional_key] = constraints[optional_key]

    return expansion


register_capability(
    SemanticCapability(
        code="READ_ONLY_CANARY",
        modes=("READ_ONLY",),
        builder=_read_only_canary_builder,
    )
)

for _code, _modes in (
    ("STRUCTURED_V2_OBJECTIVE", _STRUCTURED_V2_MODES),
    ("WORKER_JOB_V2", _STRUCTURED_V2_MODES),
    ("READ_ONLY_AUDIT", ("READ_ONLY", "READ_ONLY_SQL")),
    ("REPOSITORY_CONTRACT_AUDIT", ("READ_ONLY",)),
    ("REPOSITORY_ARCHITECTURE_AUDIT", ("READ_ONLY",)),
    ("READ_ONLY_SQL_AUDIT", ("READ_ONLY_SQL",)),
    ("MUTATION_V2", ("MUTATION",)),
    ("FRONTEND_BUILD_CERTIFICATION", ("FRONTEND_BUILD_CERTIFICATION", "READ_ONLY")),
):
    register_capability(
        SemanticCapability(
            code=_code,
            modes=_modes,
            builder=_structured_v2_objective_builder,
        )
    )

